rule.definition:
a!localVariables(
  local!wordsIncludedActions: #"SYSTEM_SYSRULES_queryRecordType_v4"(
    recordType: #"urn:appian:record-type:v1:d81be1e7-776a-47cf-976a-1460af8a706c",
    fields: {
      #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/36087fb3-3349-4af6-8c6c-307162c97f4e",
      #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477"
    },
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/36087fb3-3349-4af6-8c6c-307162c97f4e",
          operator: "in",
          value: { 4, 5, 6 }
        )
      },
      ignoreFiltersWithEmptyValues: true
    ),
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 100)
  ).data,
  local!fromDomain: if(
    and(
      a!isNotNullOrEmpty(ri!FROM_EMAIL),
      a!isInText(index(ri!FROM_EMAIL, 1, null), "@")
    ),
    lower(right(
      index(ri!FROM_EMAIL, 1, null),
      len(index(ri!FROM_EMAIL, 1, null)) - find("@", index(ri!FROM_EMAIL, 1, null))
    )),
    null
  ),
  #"SYSTEM_SYSRULES_queryRecordType_v4"(
    recordType: #"urn:appian:record-type:v1:d81be1e7-776a-47cf-976a-1460af8a706c",
    fields: {
      #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/b0ec07a4-545b-4772-b588-cf1bc199c032",
      #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477",
      #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/36087fb3-3349-4af6-8c6c-307162c97f4e"
    },
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "OR",
      filters: {
        /*   Condición 1: (Verifico las reglas del DE) — email completo O dominio   */
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477",
          operator: "in",
          value: append(
            if(a!isNotNullOrEmpty(ri!FROM_EMAIL), { lower(index(ri!FROM_EMAIL, 1, null)) }, {}),
            if(a!isNotNullOrEmpty(local!fromDomain), { local!fromDomain }, {})
          ),
          applyWhen: a!isNotNullOrEmpty(ri!FROM_EMAIL)
        ),
        /* Condición 2: (Verifico las reglas del PARA) */
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477",
          operator: "in",
          value: ri!TO_EMAILS,
          applyWhen: a!isNotNullOrEmpty(ri!TO_EMAILS)
        ),
        /* Condición 3: (Verifico las reglas del CC) */
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477",
          operator: "in",
          value: ri!CC_EMAILS,
          applyWhen: a!isNotNullOrEmpty(ri!CC_EMAILS)
        ),
        /* Condición 4: (Verifico las reglas del SUBJECT) */
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477",
          operator: "in",
          value: #"SYSTEM_SYSRULES_forEach"(
            items: local!wordsIncludedActions[wherecontains(
              4, local!wordsIncludedActions[#"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/36087fb3-3349-4af6-8c6c-307162c97f4e"]
            )],
            expression: if(
              a!isInText(
                lower(ri!SUBJECT),
                lower(
                  fv!item[#"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477"]
                )
              ),
              lower(
                fv!item[#"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477"]
              ),
              null
            )
          ),
          applyWhen: a!isNotNullOrEmpty(ri!SUBJECT)
        ),
        /* Condición 5: (Verifico las reglas del BODY) */
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477",
          operator: "in",
          value: #"SYSTEM_SYSRULES_forEach"(
            items: local!wordsIncludedActions[wherecontains(
              5, local!wordsIncludedActions[#"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/36087fb3-3349-4af6-8c6c-307162c97f4e"]
            )],
            expression: if(
              a!isInText(
                lower(ri!BODY),
                lower(
                  fv!item[#"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477"]
                )
              ),
              lower(
                fv!item[#"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477"]
              ),
              null
            )
          ),
          applyWhen: and(a!isNotNullOrEmpty(ri!BODY), )
        ),
        /* Condición 7: (Verifico las reglas del IMPORTANCE) */
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477",
          operator: "=",
          value: ri!IMPORTANCE,
          applyWhen: a!isNotNullOrEmpty(ri!IMPORTANCE)
        ),
        /* Condición 8: (Verifico las reglas del ATTACHEMENTS ) */
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:d81be1e7-776a-47cf-976a-1460af8a706c/9031f715-b001-43e8-b07e-c67ded2f9477",
          operator: "=",
          value: ri!ATTACHEMENTS,
          applyWhen: a!isNotNullOrEmpty(ri!ATTACHEMENTS)
        )
      },
      ignoreFiltersWithEmptyValues: true
    ),
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 100)
  ).data
)
